var btns = Array.from(document.querySelectorAll('[role=dialog] button'));
window.__darkFind = btns.map(function(b){return (b.textContent||'').trim()}).filter(function(t){return t==='Dark'}).length;
var d = btns.filter(function(b){return (b.textContent||'').trim()==='Dark'})[0];
window.__darkClickAt = d ? 1 : 0;
if (d) { d.click(); window.__clickResult = 'clicked'; } else { window.__clickResult = 'missing'; }
